"""Article-specific recognition, documentary evidence and lawful searches."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
REC='https://scon.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisar&aplicacao=informativo&livre=%40CNOT%3D%27021716%27'
HOME='https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=280'
SEARCH='https://scon.stj.jus.br/SCON/pesquisar.jsp?O=JT&b=ACOR&livre=158580'
CONSENT='https://scon.stj.jus.br/SCON/GetInteiroTeorDoAcordao?dt_publicacao=09%2F06%2F2026&num_registro=202503309826'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(226,'Reconhecimento de desconhecido exige descrição prévia, alinhamento adequado, proteção cabível e registro detalhado; não é simples exibição de suspeito.',
 ['Descrever antes; pessoas semelhantes no alinhamento, quando possível, com justificativa para limitações.', 'Auto assinado pela autoridade, reconhecedor e duas testemunhas; observar proteção contra intimidação.', 'Tema 1258/STJ, julgado em junho de 2025: procedimento obrigatório na investigação e em juízo; reconhecimento inválido não sustenta condenação, prisão preventiva, recebimento da denúncia ou pronúncia.', 'Repetição não cura contaminação da memória; prova independente pode sustentar autoria. Reconhecimento válido deve combinar com outras provas.', 'Identificar pessoa anteriormente conhecida difere de reconhecer desconhecido pela memória visual.'],
 'Não transformar a expressão quando possível em dispensa geral. A proteção em juízo integra as garantias atuais, inclusive art. 217. Tema 1380/STF deve ser acompanhado; não atribuir ao STF tese definitiva com base apenas no tema pendente consultado.',
 'Vítima descreve desconhecido antes de observar alinhamento sem destaque artificial do suspeito.', 'Exibir primeiro uma foto isolada pode contaminar reconhecimento posterior; nova sessão não apaga automaticamente esse vício.',
 ['Reconhecimento irregular é mera recomendação descumprida? Não, conforme Tema 1258/STJ.', 'Prova independente pode demonstrar autoria apesar do reconhecimento inválido? Sim.'], 'Reconhecimento formal','Procedimento de identificação visual sujeito a garantias de confiabilidade.',[REC])
add(227,'Reconhecimento de objetos segue as cautelas do reconhecimento de pessoas naquilo que for aplicável.', ['Descrever características antes de apontar o objeto.', 'Registrar identificação e condições do ato.', 'Adaptar cautelas ao objeto, sem importar mecanicamente regras incompatíveis.'], 'Tema sobre reconhecimento de pessoas não se transforma automaticamente em tese idêntica para qualquer objeto.', 'Vítima descreve marca e avaria do relógio antes de identificá-lo.', 'Relógios semelhantes exigem atenção às características individualizadoras.', ['Aplicam-se todas as regras sem adaptação? Não.', 'É importante registrar como o objeto foi identificado? Sim.'], 'Reconhecimento de coisa','Identificação de objeto com cautelas pertinentes.')
add(228,'Cada reconhecedor realiza o ato separadamente, sem comunicação entre eles.', ['Separação evita influência recíproca.', 'Cada relato e resultado deve ser individualizado.'], 'Concordância construída por conversa prévia não equivale a reconhecimentos independentes.', 'Duas vítimas descrevem e reconhecem separadamente.', 'Uma vítima não deve transmitir à outra quem escolheu antes do segundo ato.', ['Podem combinar respostas antes? Não.', 'Os resultados devem ser individualizados? Sim.'], 'Independência dos relatos','Prevenção de influência entre reconhecedores.')
add(229,'Acareação confronta declarações divergentes sobre fatos relevantes entre os participantes previstos no artigo.', ['Admite acusado, testemunha e ofendido nas combinações legais.', 'Reperguntar sobre os pontos de divergência e registrar explicações.', 'Preservar silêncio, defesa e proteção especial de vítimas.'], 'Acareação não autoriza coagir acusado a falar ou expor criança vítima a confronto revitimizador.', 'Duas testemunhas divergem sobre quem estava no local e esclarecem o ponto relevante.', 'Divergência sem importância para o fato não exige acareação por si só.', ['Qualquer divergência irrelevante impõe acareação? Não.', 'O acusado conserva direito ao silêncio? Sim.'], 'Acareação','Esclarecimento de divergência relevante entre declarações.')
add(230,'Se testemunha divergente está ausente, podem ser esclarecidos os pontos com a presente e, quando conveniente, por precatória com a ausente.', ['Ler pontos divergentes à presente e registrar explicações.', 'Persistindo discordância, transmitir dados e trechos pertinentes por precatória.', 'Medida condicionada à conveniência e à ausência de demora prejudicial.'], 'Não há obrigação de atrasar todo processo para acareação por precatória sem utilidade.', 'Testemunha presente esclarece divergência e juiz avalia necessidade de ouvir a ausente.', 'Se a diligência não é conveniente e provoca atraso prejudicial, a hipótese legal não exige sua realização.', ['A precatória é sempre obrigatória? Não.', 'Devem ser identificados os pontos divergentes? Sim.'], 'Acareação por precatória','Esclarecimento de divergência envolvendo testemunha ausente.')
add(231,'As partes podem apresentar documentos em qualquer fase, ressalvadas restrições legais específicas.', ['Regra de apresentação ampla.', 'Garantir conhecimento e possibilidade de resposta da parte contrária.', 'No júri, observar antecedência e ciência previstas no art. 479.'], 'Qualquer fase não significa surpreender a defesa no plenário ou ignorar norma especial.', 'Defesa junta documento novo e permite contraditório.', 'Documento destinado a leitura no júri deve respeitar a regra específica, não somente este artigo.', ['A regra dispensa exceções legais? Não.', 'Documentos exigem contraditório? Sim.'], 'Juntada documental','Apresentação de documento ao processo, com limites específicos.')
add(232,'Documento compreende escritos e instrumentos públicos ou particulares; fotografia autenticada do documento tem valor do original.', ['Natureza pública ou privada não elimina exame de autenticidade.', 'A equivalência mencionada exige autenticação.', 'Prova digital requer análise de origem e integridade pertinente.'], 'Imagem de tela não recebe autenticidade automática só por ter sido impressa.', 'Cópia fotográfica autenticada substitui original nos termos legais.', 'Captura digital contestada demanda exame de confiabilidade e contexto, não presunção absoluta.', ['Só instrumento público é documento? Não.', 'Toda fotografia não autenticada equivale automaticamente ao original? Não.'], 'Autenticidade documental','Confiabilidade da origem e integridade do registro.')
add(233,'Cartas particulares obtidas por meio criminoso não são admitidas; destinatário pode exibi-las para defender seu direito, nos limites legais.', ['Distinguir obtenção criminosa da exibição pelo destinatário.', 'A segunda hipótese independe do consentimento do signatário.', 'Integrar proteção constitucional e limites do uso do conteúdo.'], 'Ser destinatário não autoriza praticar crime para obter outras comunicações nem exposição desnecessária.', 'Destinatário apresenta carta que recebeu para provar ameaça contra si.', 'Subtrair correspondência de terceiro por meio criminoso não se legitima pela utilidade probatória.', ['Obtenção criminosa é admitida por ser útil? Não.', 'Destinatário precisa sempre de consentimento do signatário para defender direito? Não.'], 'Correspondência particular','Comunicação privada sujeita a proteção e hipóteses de uso legítimo.',[CF])
add(234,'Ao conhecer documento relativo a ponto relevante, juiz pode determinar sua juntada, observada a estrutura acusatória e o contraditório.', ['Relevância concreta para acusação ou defesa.', 'Providência não autoriza investigação substitutiva da acusação.', 'Dar acesso às partes para manifestação.'], 'Ler a iniciativa prevista com art. 3º-A e limites constitucionais, sem transformar juiz em investigador.', 'Documento identificado em depoimento é requisitado para esclarecer ponto relevante.', 'Juiz não pode usar a regra como autorização para construir sozinho uma investigação acusatória.', ['Qualquer documento irrelevante justifica a medida? Não.', 'A juntada elimina contraditório? Não.'], 'Documento relevante','Registro pertinente ao esclarecimento de questão processual.')
add(235,'Se a autenticidade de letra ou firma em documento particular é contestada, a verificação ocorre por exame pericial.', ['Objeto é letra ou assinatura contestada.', 'Perícia deve seguir regras próprias e materiais adequados.', 'Preservar direito de não produzir ativamente prova contra si.'], 'A contestação não equivale a comprovação de falsidade; silêncio ou recusa a produzir padrão não prova autoria.', 'Assinatura contestada é comparada com padrões existentes legítimos.', 'Recusa do acusado a escrever novo padrão não autoriza tratá-lo automaticamente como falsificador.', ['Contestar autenticidade já prova falsidade? Não.', 'Há exame pericial para a controvérsia? Sim.'], 'Perícia grafotécnica','Exame técnico de escrita ou assinatura.')
add(236,'Documento em língua estrangeira pode ser juntado imediatamente; tradução é feita quando necessária, pelo profissional previsto ou pessoa idônea nomeada.', ['Juntada não depende sempre de tradução anterior.', 'Necessidade de tradução deve preservar compreensão e defesa.', 'Tradutor público; na falta, pessoa idônea nomeada pela autoridade.'], 'Não impor tradução prévia universal, nem dispensar tradução necessária para compreensão.', 'Documento estrangeiro é juntado e traduzido por ser relevante à controvérsia.', 'Conteúdo cuja tradução seja necessária não pode ficar incompreensível às partes.', ['Tradução é requisito prévio universal da juntada? Não.', 'Pessoa idônea pode ser nomeada na falta de tradutor público? Sim.'], 'Tradução necessária','Conversão linguística para compreensão do documento.')
add(237,'Públicas-formas possuem valor após conferência com o original perante a autoridade, conforme a regra do artigo.', ['Conferência autentica correspondência com o original.', 'Expressão histórica não abrange automaticamente todas as formas modernas de prova digital.'], 'Não concluir que todo documento eletrônico é inválido por não ser pública-forma: existem regimes próprios.', 'Traslado apresentado é conferido com original perante a autoridade.', 'Documento eletrônico exige exame pelo regime aplicável, não uma proibição genérica extraída deste artigo.', ['A conferência prevista é dispensável para a pública-forma? Não.', 'O artigo proíbe todo documento eletrônico? Não.'], 'Pública-forma','Cópia formal sujeita à conferência prevista.')
add(238,'Originais podem ser devolvidos após o encerramento do processo, a pedido, ouvido o Ministério Público e sem motivo relevante para conservação, ficando traslado.', ['Requerimento é necessário.', 'Ouvir Ministério Público e avaliar conservação.', 'Manter traslado nos autos.'], 'Devolução não significa apagar a prova nem destruir o registro processual.', 'Após processo findo, original é devolvido e cópia permanece.', 'Se há motivo relevante de conservação, devolução não é automática.', ['Processo findo torna toda devolução automática? Não.', 'Deve permanecer traslado? Sim.'], 'Restituição documental','Devolução de original com conservação de registro.')
add(239,'Indício é circunstância conhecida e provada que permite inferir outra por raciocínio relacionado ao fato.', ['Ponto de partida deve ser demonstrado.', 'Inferência exige nexo lógico, não mera intuição.', 'Avaliar conjunto e hipóteses alternativas.'], 'Indício não é sinônimo de boato ou suspeita sem base; prova indireta não é automaticamente inútil.', 'Registro comprovado de acesso ao local integra inferência junto a outros dados.', 'Boato de que alguém parece culpado não se torna indício só por repetição.', ['O fato de partida deve ser conhecido e provado? Sim.', 'Toda suspeita é indício jurídico? Não.'], 'Prova indiciária','Inferência a partir de circunstância demonstrada.')
add(240,'Busca pode ser domiciliar ou pessoal, com fundamentos, finalidades legais e proteção constitucional.', ['Domiciliar exige fundadas razões e hipótese legítima de ingresso.', 'Finalidades abrangem pessoas, objetos, instrumentos, documentos e elementos pertinentes nos limites do §1º.', 'Pessoal exige fundada suspeita de porte de arma proibida ou dos objetos/documentos abrangidos pelo §2º.', 'Finalidade legal não dispensa privacidade, sigilos ou controle da diligência.'], 'Fundadas razões para ingresso em casa e fundada suspeita para busca pessoal são requisitos distintos; não basta propósito genérico de colher prova.', 'Mandado individualizado permite localizar objeto relacionado ao crime em endereço determinado.', 'Busca pessoal não pode ser justificada apenas por aparência ou por objeto ilícito encontrado depois.', ['Busca tem duas modalidades previstas? Sim.', 'Finalidade útil dispensa fundamento e garantias? Não.'], 'Busca probatória','Diligência delimitada para localizar pessoa ou elemento pertinente.',[CF,HOME,SEARCH])
add(241,'A redação antiga sobre presença pessoal da autoridade deve ser lida com a inviolabilidade constitucional do domicílio.', ['Presença da polícia ou do juiz não afasta, por si, reserva judicial.', 'Sem consentimento ou exceção constitucional, ingresso domiciliar depende de determinação judicial durante o dia.'], 'Não memorizar presença da autoridade policial como dispensa atual de mandado domiciliar.', 'Policiais executam mandado válido durante o dia, após identificar-se.', 'Estar o delegado pessoalmente na porta não cria exceção constitucional de ingresso.', ['Presença do delegado basta para dispensar mandado? Não.', 'A Constituição limita a leitura do texto histórico? Sim.'], 'Reserva judicial domiciliar','Proteção constitucional contra ingresso fora das hipóteses legítimas.',[CF,HOME])
add(242,'Busca pode ser requerida pelas partes; a iniciativa judicial escrita no artigo deve observar o sistema acusatório.', ['Requerimento deve indicar fundamento e objeto.', 'Art. 3º-A impede juiz de substituir a atividade investigativa da acusação.', 'Medida precisa de decisão fundamentada e limites.'], 'A expressão de ofício não autoriza investigação ilimitada pelo julgador.', 'Parte fundamenta pedido de busca com objeto e endereço identificados.', 'Juiz não pode iniciar investigação acusatória própria invocando isoladamente este artigo.', ['Pedido de parte dispensa fundamentação? Não.', 'De ofício autoriza substituir a investigação da acusação? Não.'], 'Iniciativa da busca','Provocação e decisão da diligência dentro do modelo acusatório.')
add(243,'Mandado deve identificar local ou pessoa, indicar motivo e finalidade e conter assinaturas exigidas.', ['Casa: precisão possível e morador; pessoa: nome ou sinais identificadores.', 'Subscrição do escrivão e assinatura da autoridade.', 'Incluir ordem de prisão quando houver.', 'Documento em poder do defensor: restrição legal, ressalvada hipótese de corpo de delito; integrar prerrogativas profissionais.'], 'Mandado genérico não legitima devassa; exceção de corpo de delito não elimina outras garantias profissionais aplicáveis.', 'Mandado delimita endereço e objeto procurado.', 'Recolher toda a documentação de defesa sem vínculo ou garantia não se autoriza pela mera existência de mandado.', ['Motivo e finalidade devem constar? Sim.', 'Toda documentação do defensor é livremente apreensível? Não.'], 'Individualização do mandado','Delimitação formal do alvo e propósito da busca.')
add(244,'Busca pessoal sem mandado é possível nas hipóteses legais, com fundada suspeita concretamente relacionada a arma ou corpo de delito quando exigida.', ['Prisão, fundada suspeita qualificada e curso de busca domiciliar são hipóteses legais.', 'STJ, RHC 158580: elementos prévios e objetivos, vinculados ao objeto legal da busca.', 'Achado posterior não cria retroativamente a justificativa que faltava.'], 'Aparência, nervosismo genérico ou informação anônima isolada não bastam por si. A regra não autoriza revista indiscriminada.', 'Conduta concretamente observada e outros elementos indicam porte do objeto relacionado ao delito.', 'Encontrar droga depois de revista sem fundamento prévio não convalida automaticamente a diligência.', ['Achado posterior supre justificativa inexistente antes? Não.', 'A suspeita deve ter elementos objetivos ligados à busca? Sim.'], 'Fundada suspeita','Justificação concreta anterior para a revista probatória.',[SEARCH])
add(245,'Busca domiciliar com mandado ocorre de dia; consentimento e demais exceções constitucionais possuem requisitos próprios.', ['Mostrar e ler mandado, intimando abertura; autoridade presente identifica-se e anuncia objeto, sem afastar a Constituição.', 'Resistência pode exigir ingresso forçado legítimo e proporcional; ausência do morador exige cautelas e vizinho quando presente.', 'Solicitar entrega do objeto procurado; apreensão segue registro e custódia.', 'Auto circunstanciado com duas testemunhas presenciais.', 'Tema 280/STF: ingresso forçado sem mandado exige razões concretas de flagrante no interior, justificadas no controle posterior.'],
 'Consentimento deve ser livre e comprovado. Documentá-lo permite controle; decisões de 2026 apreciam concretamente a prova, sem regra de que todo consentimento verbal é inválido ou de que a palavra policial sempre basta.', 'Mandado diurno é apresentado, busca delimitada e apreensão documentada.', 'Sem mandado, denúncia vaga e descoberta posterior de droga não dispensam fundamentação prévia ou comprovação de consentimento válido.', ['Presença policial elimina proteção domiciliar? Não.', 'Consentimento obtido por coação legitima ingresso? Não.'], 'Ingresso domiciliar legítimo','Entrada em casa sob autorização ou exceção constitucional demonstrada.',[CF,HOME,CONSENT])
add(246,'As cautelas domiciliares também alcançam aposento ocupado em habitação coletiva e recinto profissional privado não aberto ao público.', ['Proteção acompanha uso privado do espaço.', 'Não confundir área aberta ao público com recinto profissional reservado.', 'Observar garantias específicas quando aplicáveis.'], 'Quarto de hotel ocupado não perde proteção apenas porque integra estabelecimento comercial.', 'Busca em quarto de hotel ocupado respeita requisitos de ingresso domiciliar.', 'Área de atendimento aberta ao público e sala profissional privada não têm automaticamente o mesmo regime espacial.', ['Quarto ocupado de hotel pode ter proteção domiciliar? Sim.', 'Todo espaço comercial é indiferentemente aberto à busca? Não.'], 'Domicílio protegido','Espaços privados abrangidos pelas cautelas legais.',[CF])
add(247,'Se busca domiciliar não alcançar o resultado, motivos da diligência devem ser comunicados a quem a sofreu, quando solicitados.', ['Ausência de resultado não transforma por si a busca em ilegal.', 'Informação é prestada ao interessado que a solicitar.'], 'Dever de explicar motivo não autoriza inventar fundamento depois: legalidade depende dos requisitos prévios.', 'Morador solicita e recebe motivos de busca que não localizou objeto.', 'Encontrar nada não dispensa a prestação de informação prevista quando solicitada.', ['O interessado pode solicitar motivos? Sim.', 'Resultado negativo prova automaticamente ilegalidade? Não.'], 'Comunicação dos motivos','Informação ao atingido por diligência sem resultado.')
add(248,'Busca em casa habitada deve minimizar incômodo além do indispensável ao êxito.', ['Necessidade limita intervenção.', 'Preservar dignidade, bens e espaços alheios ao objeto.', 'Força legítima não autoriza excesso.'], 'Busca não é punição antecipada nem licença para dano desnecessário.', 'Agentes limitam inspeção aos espaços pertinentes e preservam bens.', 'Destruir objeto sem necessidade para localizar a prova excede o propósito da diligência.', ['Pode causar qualquer incômodo por conveniência? Não.', 'Deve limitar-se ao indispensável? Sim.'], 'Proporcionalidade da execução','Intervenção apenas na medida necessária.')
add(249,'Busca em mulher é realizada por outra mulher se isso não importar retardamento ou prejuízo à diligência.', ['Preferência legal com condição expressa.', 'Exceção exige situação concreta, não rotina sem justificativa.', 'Dignidade e privacidade permanecem em qualquer hipótese.'], 'A condição legal não autoriza humilhação ou abuso; também não se conclui nulidade automática apenas pelo sexo do agente.', 'Agente mulher disponível realiza busca sem atraso prejudicial.', 'Urgência concretamente incompatível com espera exige análise e respeito às garantias, não licença para exposição.', ['A regra possui condição expressa? Sim.', 'A exceção permite tratamento degradante? Não.'], 'Busca e dignidade','Execução respeitosa com preferência prevista.')
add(250,'Na perseguição para apreensão, autoridade pode transpor outra jurisdição, mesmo de outro estado, cumprindo comunicação local prevista.', ['Apresentar-se à autoridade local antes ou depois, conforme urgência.', 'Perseguição inclui acompanhamento contínuo e informações fidedignas de passagem recente nas hipóteses do §1º.', 'Autoridade local pode verificar legitimidade sem frustrar a diligência.'], 'Transposição territorial não cria competência processual universal nem elimina requisitos para entrar em domicílio.', 'Perseguição urgente cruza divisa e autoridade se apresenta localmente após a diligência.', 'Uma pista vaga e antiga não configura automaticamente a perseguição descrita no artigo.', ['Pode alcançar outro estado nos termos legais? Sim.', 'A transposição dispensa requisitos domiciliares? Não.'], 'Continuidade da perseguição','Prosseguimento territorial da diligência sob condições legais.')
assert len(rows)==25
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'recognition and search units reviewed')
